css:
.d-password-visibility{width:100%;max-width:430px;min-width:0;color:var(--ink);font:inherit;font-size:14px;line-height:1.5;overflow-wrap:anywhere}
.d-password-visibility *,.d-password-visibility *::before,.d-password-visibility *::after{box-sizing:border-box}
.d-password-visibility [hidden]{display:none!important}
.d-password-visibility .d-row{display:flex;flex-wrap:wrap;align-items:center;gap:8px;margin:8px 0}
.d-password-visibility .d-note{display:block;margin:8px 0 0;color:var(--muted);font-size:12px;min-height:1.5em}
.d-password-visibility label{display:block;margin:8px 0}
.d-password-visibility input,.d-password-visibility select,.d-password-visibility textarea,.d-password-visibility button{font:inherit;color:inherit;max-width:100%;min-width:0}
.d-password-visibility input:not([type=checkbox]):not([type=radio]),.d-password-visibility select,.d-password-visibility textarea{width:100%;padding:8px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper)}
.d-password-visibility button{padding:6px 10px;border:1px solid var(--line);border-radius:var(--radius-control);background:var(--paper);cursor:pointer}
.d-password-visibility button:disabled{opacity:.5;cursor:default}
.d-password-visibility :focus-visible{outline:2px solid var(--ink);outline-offset:3px}
.d-password-visibility [aria-invalid=true]{border-color:var(--warn)!important}
.d-password-visibility .d-scroll{max-width:100%;overflow:auto}
.d-password-visibility table{width:100%;border-collapse:collapse;font-size:12px;text-align:left}
.d-password-visibility th,.d-password-visibility td{padding:7px;border-bottom:1px solid var(--line);vertical-align:top}
.d-password-visibility caption{text-align:left;font-weight:600;margin-bottom:8px}
.d-password-visibility progress{width:100%;accent-color:var(--ink)}
.d-password-visibility pre{white-space:pre-wrap;overflow-wrap:anywhere;font-size:12px}
.d-password-visibility h3,.d-password-visibility p{margin:8px 0}
.d-password-visibility [aria-pressed=true],.d-password-visibility [aria-selected=true]{border-color:var(--ink);font-weight:650}
.d-password-visibility .d-grow{flex:1;min-width:100px}
.d-password-visibility summary{cursor:pointer;padding:6px 0}
.d-password-visibility ul,.d-password-visibility ol{padding-left:24px}

init:
root => {
 const q = selector => root.querySelector(selector);
 const qa = selector => [...root.querySelectorAll(selector)];
 const say = text => { const out = q('[data-out]'); if (out) out.textContent = text; };
 ((root, q, qa, say) => {
    const input=q('[data-password]'), button=q('[data-toggle]');
    button.onclick=()=>{const start=input.selectionStart,end=input.selectionEnd;const shown=input.type==='password';input.type=shown?'text':'password';button.textContent=shown?'隐藏密码':'显示密码';button.setAttribute('aria-pressed',String(shown));if(start!==null)input.setSelectionRange(start,end);say(shown?'密码当前可见':'密码已隐藏');};
  })(root, q, qa, say);
}
